// Generated by vibelang from src/features/runs/words.ts; the migrate flow writes it again with each batch.
const flowNames = { ci: "CI", todo: "TODO", "watch/set": "Follow" };
/** Known system flows have product names; a person's own flow keeps its name. */
export const flowWords = (name) => flowNames[name] ?? name;
/** Git ref prefixes are transport details, not part of a branch name. */
export const branchWords = (ref) => ref.replace(/^refs\/heads\//, "");
